"use client";

import { useEffect, useState } from "react";
import { apiFetch } from "@/lib/api";
import { Card } from "@/components/ui/card";

type Contribution = { id: string; name: string; initials?: string | null; employeeNumber?: string | null; company: string; amountDue: number; amountPaid: number; status: string; reference?: string | null };

export function ContributionsRegister() {
  const [period, setPeriod] = useState(new Date().toISOString().slice(0, 7));
  const [companyFilter, setCompanyFilter] = useState("ALL");
  const [statusFilter, setStatusFilter] = useState("ALL");
  const [items, setItems] = useState<Contribution[]>([]);
  const [error, setError] = useState("");
  const [message, setMessage] = useState("");
  const [busy, setBusy] = useState("");
  const load = async () => { try { const result = await apiFetch<{ items: Contribution[] }>(`/accounting/contributions?period=${period}`); setItems(result.items); setError(""); } catch (reason) { setError(reason instanceof Error ? reason.message : "Unable to load contributions."); } };
  useEffect(() => { void load(); }, [period]);
  async function mark(item: Contribution, status: string) { setBusy(item.id); try { await apiFetch(`/accounting/contributions/${item.id}/mark`, { method: "POST", body: JSON.stringify({ period, status, amountPaid: status === "PAID" ? item.amountDue : 0 }) }); setMessage(`${item.name} marked ${status.toLowerCase()}.`); await load(); } catch (reason) { setError(reason instanceof Error ? reason.message : "Unable to update contribution."); } finally { setBusy(""); } }
  const companies = Array.from(new Set(items.map((item) => item.company))).sort();
  const visibleItems = items.filter((item) => (companyFilter === "ALL" || item.company === companyFilter) && (statusFilter === "ALL" || item.status === statusFilter));
  const paid = visibleItems.filter((item) => item.status === "PAID").length;
  return <section className="space-y-5"><div className="flex flex-col justify-between gap-3 md:flex-row md:items-end"><div><p className="text-[11px] font-semibold uppercase tracking-[0.16em] text-brand-500">Monthly contributions</p><h1 className="mt-2 text-3xl font-semibold text-ink">Contribution payments</h1><p className="mt-2 text-sm text-slate-500">Mark each active client contribution as paid or unpaid for the selected month.</p></div><label className="text-xs font-semibold text-slate-500">Payment month<input type="month" value={period} onChange={(event) => setPeriod(event.target.value)} className="mt-1 rounded-xl border border-line px-3 py-2.5 text-sm font-normal text-ink" /></label></div><Card className="p-4"><div className="flex flex-col gap-3 md:flex-row md:items-end"><label className="flex-1 text-xs font-semibold text-slate-500">Company<select value={companyFilter} onChange={(event) => setCompanyFilter(event.target.value)} className="mt-1 w-full rounded-xl border border-line bg-white px-3 py-2.5 text-sm font-normal text-ink"><option value="ALL">All companies</option>{companies.map((company) => <option key={company} value={company}>{company}</option>)}</select></label><label className="flex-1 text-xs font-semibold text-slate-500">Payment status<select value={statusFilter} onChange={(event) => setStatusFilter(event.target.value)} className="mt-1 w-full rounded-xl border border-line bg-white px-3 py-2.5 text-sm font-normal text-ink"><option value="ALL">All statuses</option><option value="PAID">Paid</option><option value="UNPAID">Unpaid</option><option value="PARTIAL">Partially paid</option></select></label><button onClick={() => { setCompanyFilter("ALL"); setStatusFilter("ALL"); }} className="rounded-xl border border-line px-4 py-2.5 text-sm font-semibold text-slate-700">Clear filters</button></div></Card><div className="grid gap-3 sm:grid-cols-3"><Summary label="Clients" value={visibleItems.length} /><Summary label="Paid" value={paid} /><Summary label="Outstanding" value={visibleItems.filter((item) => item.status !== "PAID").length} /></div>{error && <p className="text-sm text-rose-600">{error}</p>}{message && <p className="text-sm text-emerald-600">{message}</p>}<Card className="overflow-hidden"><div className="overflow-x-auto"><table className="w-full min-w-[820px] text-left text-sm"><thead className="bg-soft text-[11px] uppercase tracking-[0.14em] text-slate-500"><tr><th className="p-4">Client</th><th className="p-4">Company</th><th className="p-4">Monthly amount</th><th className="p-4">Status</th><th className="p-4 text-right">Actions</th></tr></thead><tbody>{visibleItems.map((item) => <tr key={item.id} className="border-t border-line"><td className="p-4"><p className="font-semibold text-ink">{item.name}</p><p className="mt-1 text-xs text-slate-500">{item.employeeNumber || "No employee number"}</p></td><td className="p-4 text-slate-600">{item.company}</td><td className="p-4 font-semibold text-ink">R{item.amountDue.toLocaleString()}</td><td className="p-4"><span className={`rounded-full px-2.5 py-1 text-xs font-semibold ${item.status === "PAID" ? "bg-emerald-50 text-emerald-700" : "bg-rose-50 text-rose-700"}`}>{item.status}</span></td><td className="p-4 text-right"><div className="flex justify-end gap-2"><button disabled={busy === item.id} onClick={() => void mark(item, "UNPAID")} className="rounded-xl border border-line px-3 py-1.5 text-xs font-semibold">Unpaid</button><button disabled={busy === item.id} onClick={() => void mark(item, "PAID")} className="rounded-xl bg-brand-500 px-3 py-1.5 text-xs font-semibold text-white">Mark paid</button></div></td></tr>)}{visibleItems.length === 0 && <tr><td colSpan={5} className="p-10 text-center text-slate-500">No contribution records match these filters.</td></tr>}</tbody></table></div></Card></section>;
}

function Summary({ label, value }: { label: string; value: number }) { return <Card className="p-4"><p className="text-[11px] font-semibold uppercase tracking-[0.14em] text-slate-500">{label}</p><p className="mt-2 text-2xl font-semibold text-ink">{value}</p></Card>; }
